75	var CITY_STORAGE_KEY = "infoWeatherCity"
76	
77	export default {
78	  private: {
79	    isDark: false,
80	    themeButtonText: "深色模式",
81	    modeLabel: "浅色",
82	    currentTime: "--:--",
83	    currentDate: "",
