261	static FtAny get_response_data(fetch_t* fetch, uv_response_t* response,
262	    ft_value_t* out)
263	{
264	    assert(fetch);
265	    if (!out) {
266	        FETCH_ERROR("arg err!");
267	        return NULL;
268	    }
269	
270	    if (!response->body) {
271	        *out = ft_from_string(fetch->ft_ctx, "");
272	        return out;
273	    }
274	
275	    switch (fetch->response_type) {
276	    case Fetch::ResponseType::JSON:
277	        *out = ft_parse_json(fetch->ft_ctx, response->body,
278	            response->size, NULL);
279	        break;
280	    default:
281	        if (fetch->type == UV_DOWNLOAD) {
282	            char* path = app_absolute_to_relative_path(
283	                FeatureGetPackageName(FeatureGetProtoHandle(fetch->feature)),
284	                response->body);
285	            assert(path);
286	            response->size = strlen(path) + 1;
287	            free(response->body);
288	            response->body = path;
289	        }
290	        if (response->body[response->size - 1] == '\0') {
291	            *out = ft_from_string(fetch->ft_ctx, response->body);
292	        } else {
293	            char* buf = static_cast<char*>(malloc(response->size + 1));
294	            if (!buf)
295	                break;
296	
297	            memcpy(buf, response->body, response->size);
298	            buf[response->size] = '\0';
299	            *out = ft_from_string(fetch->ft_ctx, buf);
300	            free(buf);
301	        }
302	        break;
303	    }
304	    return out;
305	}
