326	static void fetch_request_cb(int state, uv_response_t* response)
327	{
328	    FEATURE_NOTE_BEGIN_STR("fetch_request_cb");
329	    fetch_t* p = static_cast<fetch_t*>(response->userp);
330	    ASSERT_RET_ECHO(p, "The request has been cancelled");
331	    FETCH_INFO("");
332	    if (FeatureInstanceIsDetached(p->feature)) {
333	        FETCH_INFO("");
334	        goto exit;
335	    }
336	
337	    if (response->headers) {
338	        const char* content_length = strstr(response->headers, "Content-Length: ");
339	        const char* content_encoding = strstr(response->headers, "Content-Encoding: ");
340	        if (content_length && !content_encoding) {
341	            content_length += 16;
342	            long len = strtol(content_length, NULL, 10);
343	            if (len != LONG_MIN && len != LONG_MAX) {
344	                response->size = (size_t)len;
345	            }
346	        } else {
347	            response->size = response->body ? strlen(response->body) : 0;
348	        }
349	    }
350	
351	    FETCH_DEBUG("state:%d \nbody:%s ;\nheaders:%s", state, response->body,
352	        response->headers);
353	    if (state == UV_REQUEST_DONE) {
354	        std::string header = response->headers;
355	
356	        if (response->httpcode >= HTTP_BAD_REQUES) {
357	            FETCH_ERROR("upload err, error code: %d,msg: %s", response->httpcode,
358	                response->body);
359	        }
360	
361	        ft_value_t ft_header = ft_form_headers(p->ft_ctx, response->headers);
362	        ft_value_t result = ft_new_object(p->ft_ctx);
363	        ft_value_t res_code = ft_from_int(p->ft_ctx, (int)response->httpcode);
364	        ft_value_t res_data = ft_undefined(p->ft_ctx);
365	
366	        if (p->response_type == Fetch::ResponseType::NONE) {
367	            std::map<std::string, std::string> headers;
368	            if (check_header(p->ft_ctx, &ft_header, headers)) {
369	                p->response_type = get_cy_from_response(headers);
370	            }
371	        }
372	
373	        get_response_data(p, response, &res_data);
374	
375	        ft_obj_set_property(p->ft_ctx, result, "code", res_code);
376	        ft_obj_set_property(p->ft_ctx, result, "headers", ft_header);
377	        ft_obj_set_property(p->ft_ctx, result, "data", res_data);
378	
379	        if (ft_get_type(p->ft_ctx, res_data) >= 0) {
380	            FeaturePromiseResolve(p->feature, p->pid, &result);
381	        } else {
382	            FeaturePromiseReject(p->feature, p->pid, ErrorCode::IOERROR, "responseType dosen't match response data");
383	        }
384	        ft_free_value(p->ft_ctx, result);
385	        InspectHostNetResponse(p->request, response, InspectHostNetGetCurrentReqId(), header.c_str());
386	
387	    } else if (state == REQUEST_CANCEL) {
388	        FETCH_INFO(USER_ABORT_MSG);
389	        InspectHostNetLoadingFailed(true);
390	        uv_request_delete(p->request);
391	    } else {
392	        FETCH_ERROR("upload err, error code: %d,msg: %s", response->httpcode,
393	            response->body);
394	        InspectHostNetLoadingFailed(true);
395	        ErrorCode error_code = ErrorCode::GENERAL;
396	#ifdef CONFIG_LIB_CURL
397	        error_code = map_curl_to_custom_error(response->httpcode);
398	#endif
399	        FeaturePromiseReject(p->feature, p->pid, error_code, response->body);
400	    }
401	
402	exit:
403	    // request done,uv_request  has been released
404	    PROFILE_FEATURE_MODULE_LOG_END("Fetch::fetch", p->url ? p->url : "");
405	    fetch_free(p);
406	    FEATURE_NOTE_END_STR("fetch_request_cb");
407	}
