409	static bool request_create(fetch_t* fetch, system_fetch_FetchPara* obj,
410	    Fetch::MethodType method,
411	    std::map<std::string, std::string>& headers)
412	{
413	    FEATURE_NOTE_BEGIN_STR("fetch_request_create");
414	    request_context_t* p = get_request_context(fetch->feature);
415	    // create reques
416	    ASSERT_RET_NULL(0 == uv_request_create(&fetch->request));
417	    FETCH_DEBUG("request:%p", fetch->request);
418	
419	    // encode url
420	    FEATURE_NOTE_BEGIN_STR("fetch_request_decode");
421	    const char* decode = url_decode(obj->url);
422	    if (strcmp(decode, obj->url) == 0) {
423	        fetch->url = url_encode(decode);
424	    } else {
425	        fetch->url = strdup(obj->url);
426	    }
427	
428	    free((void*)decode);
429	    FEATURE_NOTE_END_STR("fetch_request_decode");
430	
431	    PROFILE_FEATURE_MODULE_LOG_BEGIN("Fetch::fetch", fetch->url);
432	
433	    // set url
434	    uv_request_set_url(fetch->request, fetch->url);
435	
436	    // set method
437	    if (method) {
438	        uv_request_set_method(fetch->request, Fetch::method_type[method]);
439	    }
440	
441	    uv_request_set_data(
442	        fetch->request,
443	        (fetch->content->data.empty() ? (void*)fetch->content->buf_type_data
444	                                      : fetch->content->data.c_str()),
445	        fetch->content->size);
446	
447	    // set header
448	    for (auto [key, val] : headers) {
449	        FETCH_DEBUG("header: %s", std::string(key + ": " + val).c_str());
450	        uv_request_append_header(fetch->request,
451	            std::string(key + ": " + val).c_str());
452	    }
453	
454	    // set timeout
455	    if (obj->timeout) {
456	        uv_request_set_timeout(fetch->request, obj->timeout);
457	    }
458	
459	    // Set request to DOWNLOAD or FETCH
460	    uv_request_set_atrribute(fetch->request, fetch->type,
461	        (void*)fetch->filename.c_str());
462	    // set to userp
463	    uv_request_set_userp(fetch->request, fetch);
464	
465	#if CONFIG_FEATURE_LOG_LEVEL == FEATURE_LOG_LEVEL_DEBUG
466	    uv_request_set_verbose(fetch->request);
467	#endif
468	
469	    InspectHostNetRequest(fetch->request, Fetch::method_type[method], InspectHostNetGetReqId());
470	
471	    // start upload
472	    uv_request_commit(p->handle, fetch->request, fetch_request_cb);
473	
474	    FEATURE_NOTE_END_STR("fetch_request_create");
475	    return true;
476	}
