620	void system_fetch_wrap_fetch(FeatureInstanceHandle feature, AppendData append_data, FtPromiseId pid, system_fetch_FetchPara* obj)
621	{
622	    FEATURE_NOTE_BEGIN_STR("wrap_fetch");
623	    ft_context_ref ft_ctx = FeatureGetContext(feature);
624	    assert(ft_ctx);
625	    const char* msg = "";
626	    int code = 0;
627	    fetch_t* fetch = NULL;
628	    Fetch::MethodType method;
629	    std::map<std::string, std::string> headers;
630	    request_context_t* p = get_request_context(feature);
631	    content_t* content = new content_t();
632	    SET_JS_ERROR(content, ErrorCode::GENERAL, "create content_t err");
633	
634	    FETCH_DEBUG(
635	        "url:%s\ndata:%p\nheader:%p\nmethod:%p\nresponseType:%p\n",
636	        obj->url, obj->data, obj->header, obj->method, obj->responseType);
637	
638	    // Check necessary parameters
639	    obj->timeout = obj->timeout > 0 ? obj->timeout : DEFAULT_TIMEOUT;
640	    SET_ARGERROR(check_url(obj->url), "invalid url");
641	
642	    // Check for non-essential parameters
643	    SET_ARGERROR(get_method(obj->method, &method), "invalid method");
644	
645	    if (check_any(obj->header)) {
646	        SET_ARGERROR(check_header(ft_ctx, obj->header, headers),
647	            "invalid headers");
648	    }
649	
650	    if (check_any(obj->data) && (method != Fetch::MethodType::GET && method != Fetch::MethodType::HEAD)) {
651	        SET_ARGERROR(get_pdata_and_content_type(
652	                         ft_ctx, obj->data, get_cy_from_header(headers), content),
653	            "invalid data");
654	    } else {
655	        headers["Content-Type"] = "text/plain; charset=utf-8";
656	    }
657	
658	    // create fetch context
659	    fetch = fetch_create(feature, ft_ctx, pid, obj, p->pkg, content);
660	    SET_JS_ERROR(fetch, ErrorCode::GENERAL, "create native fetch err");
661	
662	    // create curl request
663	    SET_JS_ERROR(request_create(fetch, obj, method, headers),
664	        ErrorCode::GENERAL, "create request err");
665	    // add in list
666	    weakref_list_initialize(&fetch->node);
667	    weakref_list_add_tail(&p->linklist, &fetch->node);
668	
669	    FEATURE_NOTE_END_STR("wrap_fetch");
670	    return;
671	err:
672	    FETCH_DEBUG("msg:%s,code:%d", msg, code);
673	    FeaturePromiseReject(feature, pid, code, msg);
674	    FEATURE_NOTE_END_STR("wrap_fetch");
675	}
