## 1. 页面生命周期 & 调用链 (`pages/index.ux`)

```javascript
// 页面生命周期
onInit() {
  this.isDark = getThemeSync()
  this.updateClock()
  this.updateDate()
},

onShow() {
  this.updateClock()
  this.updateDate()
  this.loadWeather()  // ← 每次显示页面都会触发
},

// 串行调用链
loadWeather() {
  var self = this
  storage.get({
    key: "infoWeatherCity",
    success: function(data) {
      var city = data || "北京"
      self.fetchWeather(city)  // ← 闭包引用 self
    },
    fail: function() {
      self.fetchWeather("北京")
    }
  })
},

fetchWeather(city) {
  var self = this
  self.weatherSummary = city + " 获取天气中..."
  getWeather(city).then(function(info) {  // ← Promise 回调
    self.weatherSummary = info.title + " " + info.message + " " + info.subtitle
    self.loadNews()  // ← 继续串行加载新闻
  }).catch(function() {
    self.weatherSummary = city + " 天气获取失败"
    self.loadNews()
  })
}
```

**注意**：`storage.get()` 只传了 `success` 和 `fail`，**没有传 `complete` 回调**。

---

## 2. 网络请求封装 (`common/services.js`)

```javascript
import fetch from "@system.fetch"

function request(options) {
  var url = options.url
  var method = options.method || "GET"

  return new Promise(function(resolve, reject) {
    fetch.fetch({
      url: url,
      method: method,
      header: options.header || {},
      responseType: options.responseType || "json",
      success: function(res) {        // ← native 成功回调
        var code = res.code || res.statusCode
        var data = res.data !== undefined ? res.data : res.result
        if (typeof data === "string") {
          data = parseData(data)
        }
        if (code >= 200 && code < 300) {
          resolve(data)               // ← resolve Promise
        } else {
          reject(new Error("HTTP " + code))
        }
      },
      fail: function(data, code) {    // ← native 失败回调
        reject(new Error("network error"))
      }
    })
  })
}

export function getWeather(city) {
  var query = encodeQuery({
    city: city,
    extended: true,
    forecast: true,
    indices: true
  })
  return request({
    url: "https://uapis.cn/api/v1/misc/weather" + "?" + query
  }).then(function(data) {
    // 处理天气数据...
    return { title: district, subtitle: desc, message: temp + "°C", ... }
  })
}
```

---

## 3. 关键问题点

| 问题 | 说明 |
|------|------|
| **闭包** | `self = this` 保存页面实例引用，回调通过闭包访问 |
| **storage.get() 缺少 complete 回调** | 只传了 success/fail，没传 complete |
| **Promise 链** | `fetch.fetch()` 用 success/fail 回调 → resolve Promise → `.then()` 回调 |
| **串行依赖** | weather → news → history，任一环节崩溃影响后续 |

---

## 4. 崩溃时序

```
onShow() 
  → storage.get({key: "infoWeatherCity", success: ..., fail: ...})  // 没传 complete
  → [native] storage_cb() 异步回调
  → finish_callback() 尝试调用 complete callback (undefined)
  → FeatureInvokeCallback() 访问无效指针
  → Data Abort 💥
```

技术支持可以重点关注 `storage_impl.cpp` 中 `finish_callback()` 对 undefined callback 的处理逻辑喵～

