import fetch from "@system.fetch"

function request(options) {
  var url = options.url
  var method = options.method || "GET"
  var responseType = options.responseType || "json"

  console.log("request: " + method + " " + url)

  return new Promise(function (resolve, reject) {
    fetch.fetch({
      url: url,
      method: method,
      header: options.header || {},
      responseType: responseType,
      success: function (res) {
        console.log("request success: code=" + (res.code || res.statusCode) + ", url=" + url)
        try {
          var code = res.code || res.statusCode
          var data = res.data !== undefined ? res.data : res.result

          if (typeof data === "string") {
            data = parseData(data)
          }

          if (code >= 200 && code < 300) {
            resolve(data)
          } else if (data && typeof data === "object" && Object.keys(data).length > 0) {
            resolve(data)
          } else {
            reject(new Error("HTTP " + code))
          }
        } catch (e) {
          reject(e)
        }
      },
      fail: function (data, code) {
        console.log("request fail: url=" + url + ", code=" + code)
        reject(new Error("network error"))
      }
    })
  })
}

export function getWeather(city) {
  var query = encodeQuery({
    city: city,
    extended: true,
    forecast: true,
    indices: true
  })

  return request({
    url: "https://uapis.cn/api/v1/misc/weather" + "?" + query
  }).then(function (data) {
    if (!data || !data.city) {
      return {
        ready: false,
        title: city,
        subtitle: "查询失败",
        message: "天气数据暂不可用",
        details: [],
        detailsExtra: [],
        indexes: [],
        forecasts: [],
        alerts: []
      }
    }

    var temp = data.temperature !== undefined ? data.temperature : "--"
    var desc = data.weather || "未知"
    var feelsLike = data.feels_like !== undefined ? data.feels_like : "--"
    var humidity = data.humidity !== undefined ? data.humidity + "%" : "--"
    var windDir = data.wind_direction || "--"
    var windPower = data.wind_power || "--"
    var district = data.city || city

    return {
      ready: true,
      title: district,
      subtitle: desc,
      message: temp + "°C"
    }
  })
}

export function getLatestNews(options) {
  var params = options || {}
  var categories = params.categories && params.categories.length ? params.categories.join(",") : ""

  var query = encodeQuery({
    language: "zh",
    country: "CN",
    category: categories,
    page_size: params.pageSize || 20,
    apiKey: "I_gqH5IB0yC8eS7mhIVx7LmQkx2IpDOtmCI6WTsksar1EFbA"
  })

  return request({
    url: "https://api.currentsapi.services/v1/latest-news" + "?" + query
  }).then(function (data) {
    if (!data || data.status !== "ok" || !data.news) {
      return []
    }
    return data.news.map(normalizeNews).filter(function (item) {
      return item && isTrustedDomain(item.url)
    })
  })
}

export function getTodayInHistory() {
  return request({
    url: "https://tmini.net/api/today?type=json"
  }).then(function (data) {
    if (!data || data.code !== 200 || !data.events) {
      return []
    }
    return data.events.slice(0, 5).map(function (item) {
      return {
        title: item.title || "",
        year: item.year || "",
        desc: item.desc || "",
        link: item.link || ""
      }
    })
  })
}
